from collections import deque

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            y0 = min(y for y, _ in cells)
            y1 = max(y for y, _ in cells)
            x0 = min(x for _, x in cells)
            x1 = max(x for _, x in cells)
            if y1-y0 != x1-x0 or y1-y0 < 2:
                continue
            border = {(y,x) for y in range(y0,y1+1) for x in range(x0,x1+1)
                      if y in (y0,y1) or x in (x0,x1)}
            if set(cells) != border:
                continue
            if any(grid[y][x] != bg for y in range(y0+1,y1) for x in range(x0+1,x1)):
                continue
            ih, iw = y1-y0-1, x1-x0-1
            fill = 7 if ih % 2 == 1 and iw % 2 == 1 else 2
            for y in range(y0+1,y1):
                for x in range(x0+1,x1):
                    out[y][x] = fill
    return out

